CREATE TABLE users(id BIGINT PRIMARY KEY,username VARCHAR(80) UNIQUE NOT NULL,salt CHAR(32) NOT NULL,password_hash CHAR(64) NOT NULL,role VARCHAR(10) NOT NULL);
